// 方言层（PostgreSQL）：把查询层书写的 SQLite 方言 SQL 在执行前改写为 PG 等价形式。
//
// adapter 与协议层不出现任何方言分支——全部差异收敛在本包的改写器与驱动包装器：
//   - 占位符   ?        → $1..$N（pgx 只认 $N）
//   - 大小写   LIKE     → ILIKE（SQLite LIKE 对 ASCII 不区分大小写，PG 需 ILIKE 等价）
//   - 时间默认 CURRENT_TIMESTAMP → to_char(...AT TIME ZONE 'UTC'...)（SQLite 语义为
//     UTC 秒级字符串；PG 直接赋给 TEXT 列会因类型不匹配失败，改为显式格式化）
//   - 自增主键 INTEGER PRIMARY KEY AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
//   - 类型     INTEGER  → BIGINT（SQLite INTEGER 本就是 64 位；PG INTEGER 仅 32 位，
//     缓存体积/计数列会溢出）、DATETIME → TEXT（全部读写按字符串进行）
//   - 聚合     SUM(...) → SUM(...)::int8（PG 的 SUM(bigint) 返回 numeric，pgx stdlib
//     以 string 呈现，database/sql 不支持 string→int64 扫描）
//
// 改写基于词法扫描（跳过字符串字面量与注释），不以字符串替换碰运气；
// 改写器有全量用例测试（dialect_test.go），新增 SQL 形态时同步补用例。
package database

import (
	"strconv"
	"strings"
	"sync"
)

// pgNowExpr CURRENT_TIMESTAMP 的 PG 等价表达式：UTC、秒级、与 SQLite 的
// "YYYY-MM-DD HH:MM:SS" 输出格式一致（外层括号保证在 DEFAULT 等任意子句位置可用）。
const pgNowExpr = `(to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))`

// tokenKind 词法单元类别。
type tokenKind int

const (
	tokOther        tokenKind = iota // 标点/空白等其余字符
	tokWord                          // 标识符/关键字 [A-Za-z_][A-Za-z0-9_]*
	tokParam                         // ? 占位符
	tokString                        // '...' 字符串字面量（'' 转义）或 "..." 标识符引用
	tokLineComment                   // -- 行注释
	tokBlockComment                  // /* 块注释
)

type token struct {
	kind tokenKind
	text string
}

// scanTokens SQL 词法扫描：正确跳过字符串字面量与两种注释（其中的关键字与 ? 不参与改写）。
func scanTokens(sql string) []token {
	var toks []token
	i, n := 0, len(sql)
	flushOther := func(start, end int) {
		if end > start {
			toks = append(toks, token{tokOther, sql[start:end]})
		}
	}
	otherStart := 0
	for i < n {
		c := sql[i]
		switch {
		case c == '\'' || c == '"':
			quote := c
			flushOther(otherStart, i)
			j := i + 1
			for j < n {
				if sql[j] == quote {
					if j+1 < n && sql[j+1] == quote { // '' / "" 转义
						j += 2
						continue
					}
					j++
					break
				}
				j++
			}
			if j > n {
				j = n
			}
			toks = append(toks, token{tokString, sql[i:j]})
			i = j
			otherStart = i
		case c == '-' && i+1 < n && sql[i+1] == '-':
			flushOther(otherStart, i)
			j := strings.IndexByte(sql[i:], '\n')
			if j < 0 {
				j = n
			} else {
				j = i + j + 1
			}
			toks = append(toks, token{tokLineComment, sql[i:j]})
			i = j
			otherStart = i
		case c == '/' && i+1 < n && sql[i+1] == '*':
			flushOther(otherStart, i)
			j := strings.Index(sql[i+2:], "*/")
			if j < 0 {
				j = n
			} else {
				j = i + 2 + j + 2
			}
			toks = append(toks, token{tokBlockComment, sql[i:j]})
			i = j
			otherStart = i
		case c == '?':
			flushOther(otherStart, i)
			toks = append(toks, token{tokParam, "?"})
			i++
			otherStart = i
		case isWordByte(c, true):
			flushOther(otherStart, i)
			j := i + 1
			for j < n && (isWordByte(sql[j], true) || isWordByte(sql[j], false)) {
				j++
			}
			toks = append(toks, token{tokWord, sql[i:j]})
			i = j
			otherStart = i
		default:
			i++
		}
	}
	flushOther(otherStart, n)
	return toks
}

func isWordByte(c byte, start bool) bool {
	switch {
	case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c == '_':
		return true
	case !start && c >= '0' && c <= '9':
		return true
	}
	return false
}

// isBlank 抑或纯空白的 Other 单元（lookahead 跳过用）。
func isBlank(t token) bool {
	return t.kind == tokOther && strings.TrimSpace(t.text) == ""
}

// nextWords 返回从 i 起跳过纯空白后的连续大写关键字（最多 max 个；遇到非单词即止）。
func nextWords(toks []token, i, max int) []string {
	var words []string
	for ; i < len(toks) && len(words) < max; i++ {
		if isBlank(toks[i]) {
			continue
		}
		if toks[i].kind != tokWord {
			break
		}
		words = append(words, strings.ToUpper(toks[i].text))
	}
	return words
}

// rewriteForPostgres 按 Package 注释中的规则改写 SQL（DDL 与 DML 通用）。
// 改写是纯函数（同一输入恒同一输出），经有界缓存复用：查询层 SQL 绝大多数是
// 代码内常量字符串，避免每条执行重复词法扫描；动态拼接（IN 批量占位符）的
// 种类同样有界。容量满时整体清空重建——淘汰策略的复杂度不值得引入。
const rewriteCacheMax = 1024

var (
	rewriteMu    sync.RWMutex
	rewriteCache = make(map[string]string)
)

func rewriteForPostgres(sql string) string {
	rewriteMu.RLock()
	cached, ok := rewriteCache[sql]
	rewriteMu.RUnlock()
	if ok {
		return cached
	}
	out := rewriteScan(sql)
	rewriteMu.Lock()
	if len(rewriteCache) >= rewriteCacheMax {
		rewriteCache = make(map[string]string, rewriteCacheMax/2)
	}
	rewriteCache[sql] = out
	rewriteMu.Unlock()
	return out
}

// rewriteScan 词法扫描 + 按规则改写（缓存未命中路径）。
func rewriteScan(sql string) string {
	toks := scanTokens(sql)
	var b strings.Builder
	b.Grow(len(sql) + 64)
	param := 0
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		switch t.kind {
		case tokParam:
			param++
			b.WriteByte('$')
			b.WriteString(strconv.Itoa(param))
		case tokWord:
			switch strings.ToUpper(t.text) {
			case "LIKE":
				b.WriteString("ILIKE")
			case "CURRENT_TIMESTAMP":
				b.WriteString(pgNowExpr)
			case "DATETIME":
				b.WriteString("TEXT")
			case "INTEGER":
				// INTEGER PRIMARY KEY AUTOINCREMENT → BIGINT IDENTITY（含约束顺序）
				if w := nextWords(toks, i+1, 3); len(w) == 3 && w[0] == "PRIMARY" && w[1] == "KEY" && w[2] == "AUTOINCREMENT" {
					b.WriteString("BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY")
					i = skipWords(toks, i+1, 3)
					continue
				}
				b.WriteString("BIGINT")
			case "SUM":
				b.WriteString("SUM")
				i = rewriteSumCast(toks, i, &b)
			default:
				b.WriteString(t.text)
			}
		default:
			b.WriteString(t.text)
		}
	}
	return b.String()
}

// rewriteSumCast SUM(...) 补 ::int8（PG 的 SUM(bigint) 返回 numeric，经 pgx stdlib
// 呈现为 string，database/sql 无法扫描进 int64）。从 SUM 的下一个单元起消费到
// 配对的右括号，返回新的下标（调用方 for 循环继续）。SUM 后无括号时原样保留。
// Other 单元可能把 ")"、数字、"," 合并成一个 token（如 "),0)"），必须在 token 内
// 逐字符跟踪深度：深度归零处即 SUM 表达式终点，余下字符照常输出后再接 ::int8。
func rewriteSumCast(toks []token, sumIdx int, b *strings.Builder) int {
	// 找到起始左括号（跳过空白）
	j := sumIdx + 1
	for j < len(toks) && isBlank(toks[j]) {
		j++
	}
	if j >= len(toks) || toks[j].kind != tokOther || !strings.Contains(toks[j].text, "(") {
		return sumIdx // 形态异常（无括号）：不改写，交给 PG 报错暴露
	}
	depth := 0
	started := false
	for ; j < len(toks); j++ {
		t := toks[j]
		if t.kind != tokOther {
			b.WriteString(t.text)
			continue
		}
		for k := 0; k < len(t.text); k++ {
			c := t.text[k]
			switch c {
			case '(':
				depth++
				started = true
			case ')':
				depth--
			}
			b.WriteByte(c)
			if started && depth == 0 {
				b.WriteString("::int8")
				b.WriteString(t.text[k+1:]) // 同一 Other 单元的剩余字符（如 "),0)" 的 ",0)"）
				return j
			}
		}
	}
	// 未闭合：原样输出（PG 会报语法错误）
	return j - 1
}

// skipWords 跳过 start 起的 n 个单词单元与夹在其间的空白，返回最后一个单词的下标。
func skipWords(toks []token, start, n int) int {
	count := 0
	for i := start; i < len(toks) && count < n; i++ {
		if isBlank(toks[i]) {
			continue
		}
		if toks[i].kind != tokWord {
			break
		}
		count++
		if count == n {
			return i
		}
	}
	return start - 1
}

// isPragma 是否为 SQLite PRAGMA 语句（PG 侧由驱动包装器转为 no-op）。
func isPragma(query string) bool {
	return strings.HasPrefix(strings.ToUpper(strings.TrimSpace(query)), "PRAGMA")
}
